python3 -c $'import sys,json,math\nfrom collections import Counter\nA="COSMIC_LOVE_IS_THE_SOLUTION_FOR_EVERYTHING"\ndef G(b):\n n=1\n for x in b:n=n*257+x+1\n return n\ndef D(n):\n if n<1:raise ValueError("bad code")\n a=[]\n while n>1:\n  n,r=divmod(n,257)\n  if r==0:raise ValueError("bad digit")\n  a.append(r-1)\n return bytes(a[::-1])\ns=open(sys.argv[1],"rb").read()\nn=G(s)\nif D(n)!=s:raise ValueError("roundtrip failed")\nV=sorted(set(s));P=[];c=2\nwhile len(P)<len(V):\n if all(c%p for p in P if p*p<=c):P.append(c)\n c+=1\nM=dict(zip(V,P));I={v:k for k,v in M.items()}\nif bytes(I[M[x]] for x in s)!=s:raise ValueError("prime failed")\nC=Counter(s);H=-sum((v/len(s))*math.log2(v/len(s)) for v in C.values())\nT=[A]*len(s);F=0 if len(set(T))==1 else None\nprint(json.dumps({"system":"IMMORTALITY-CONTINUITY-CAPSULE","version":"0.1-research","status":"RESEARCH_ONLY","role":"NODE_INDEPENDENT","source_bytes":len(s),"godel257_source_hex":format(n,"x"),"godel_roundtrip":True,"prime_roundtrip":True,"logical_atoms":len(V),"H_initial_bytes":round(H,8),"H_final_symbolic":F,"attractor":A,"medical_effect_proven":False,"global_control":False},separators=(",",":")))' "$0"
